// CROSS-MACHINE FLAGSHIP TEST:
// local machine (A) codex-protocol client -> SSH tunnel -> facade on server
// (B, <SERVER_IP>) -> gateway -> claude CLI on the server (DeepSeek).
//  1) initialize
//  2) thread/list  -> shows the server's claude sessions
//  3) thread/resume the server session -> gateway on B spawns claude there
//  4) turn/start   -> reply generated by claude ON THE SERVER
// Usage: node test-remote.mjs <serverSessionId>

import { WebSocket } from 'ws';

const token = '<TEST_TOKEN>';
const serverSessionId = process.argv[2];
if (!serverSessionId) { console.error('usage: node test-remote.mjs <serverSessionId>'); process.exit(2); }

const ws = new WebSocket(`ws://127.0.0.1:17689?token=${encodeURIComponent(token)}`);
let nextId = 1;
const pending = new Map();
const notes = [];
let gotTurnCompleted = null, gotReply = null, threadList = null;

ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(String(ev.data));
  if (msg.id !== undefined && pending.has(msg.id)) {
    const p = pending.get(msg.id); pending.delete(msg.id);
    if (msg.error) p.reject(new Error(msg.error.message)); else p.resolve(msg.result);
  } else if (msg.method) {
    notes.push(msg.method);
    if (msg.method === 'item/completed') gotReply = JSON.stringify(msg.params?.item?.content ?? []);
    if (msg.method === 'turn/completed') gotTurnCompleted = msg.params;
  }
});
const call = (m, p) => new Promise((res, rej) => {
  const id = nextId++; pending.set(id, { resolve: res, reject: rej });
  ws.send(JSON.stringify({ jsonrpc: '2.0', id, method: m, params: p }));
  setTimeout(() => { if (pending.has(id)) { pending.delete(id); rej(new Error('timeout ' + m)); } }, 120_000);
});

ws.addEventListener('open', async () => {
  try {
    await call('initialize', { clientInfo: { name: 'mix-remote-probe', title: 'remote probe', version: '0.1.0' } });
    console.log('[1] initialize via tunnel OK');

    threadList = await call('thread/list', {});
    const ids = (threadList?.data ?? []).map((t) => t.id);
    console.log('[2] thread/list:', ids.length, 'threads on SERVER:', ids.map((i) => i.slice(0, 18)).join(', '));

    const target = `claude:${serverSessionId}`;
    await call('thread/resume', { threadId: target });
    console.log('[3] thread/resume', target, 'OK (gateway on B spawned claude there)');

    await call('turn/start', { threadId: target, input: [{ type: 'text', text: 'Reply with exactly: CROSS-MACHINE-OK' }] });
    console.log('[4] turn/start sent; waiting for claude on the SERVER…');
    const t0 = Date.now();
    while (Date.now() - t0 < 120_000 && !gotTurnCompleted) await new Promise((r) => setTimeout(r, 500));

    const ok = /CROSS-MACHINE-OK/.test(gotReply ?? '') && Boolean(gotTurnCompleted);
    console.log('[5] reply:', (gotReply ?? '').slice(0, 120));
    console.log('\n=== CROSS-MACHINE RESULT ===');
    console.log('server sessions visible from local:', (threadList?.data ?? []).some((t) => t.id === target));
    console.log('turn completed with expected reply:', ok);
    console.log('notification methods:', [...new Set(notes)].join(', '));
    console.log('VERDICT:', ok ? 'PASS ✅' : 'FAIL ❌');
    process.exit(ok ? 0 : 1);
  } catch (e) { console.log('FATAL:', e.message); process.exit(1); }
});
setTimeout(() => { console.log('TIMEOUT'); process.exit(3); }, 150_000);
